// ----- Định vị kiểu Leaflet.Locate (như nút tâm ngắm của trang gis-binhtan) -----
// watchPosition liên tục, chấm xanh + vòng sai số, bản đồ bám theo vị trí cho tới khi người dùng tự kéo/phóng bản đồ.
// Bấm nút khi đã kéo đi chỗ khác: quay về vị trí. Bấm khi đang ở vị trí: tắt định vị.
const LOC = {id:null, follow:false, last:null, first:true};
function locCircle(lng, lat, r){
  const pts = [], k = r / 6378137 * 180 / Math.PI, kx = k / Math.cos(lat * Math.PI / 180);
  for (let i = 0; i <= 64; i++) { const a = i / 64 * 2 * Math.PI; pts.push([lng + kx * Math.sin(a), lat + k * Math.cos(a)]); }
  return pts;
}
function locDraw(p){
  const lng = p.coords.longitude, lat = p.coords.latitude, acc = p.coords.accuracy || 0;
  const d = {type:'FeatureCollection', features:[{type:'Feature', properties:{k:'c'}, geometry:{type:'Polygon', coordinates:[locCircle(lng, lat, acc)]}},
    {type:'Feature', properties:{k:'p'}, geometry:{type:'Point', coordinates:[lng, lat]}}]};
  const s = map.getSource('me'); if (s) { s.setData(d); return; }
  map.addSource('me', {type:'geojson', data:d});
  map.addLayer({id:'me-acc', type:'fill', source:'me', filter:['==', ['get','k'], 'c'], paint:{'fill-color':'#136aec', 'fill-opacity':.15}});
  map.addLayer({id:'me-accl', type:'line', source:'me', filter:['==', ['get','k'], 'c'], paint:{'line-color':'#136aec', 'line-width':1.5, 'line-opacity':.6}});
  map.addLayer({id:'me-dot', type:'circle', source:'me', filter:['==', ['get','k'], 'p'], paint:{'circle-radius':8, 'circle-color':'#2a93ee', 'circle-stroke-color':'#fff', 'circle-stroke-width':3}});
}
function locShow(on){ ['me-acc', 'me-accl', 'me-dot'].forEach(id => { if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', on ? 'visible' : 'none'); }); }
function locView(p){
  const c = locCircle(p.coords.longitude, p.coords.latitude, Math.max(p.coords.accuracy || 0, 15)), xs = c.map(q => q[0]), ys = c.map(q => q[1]);
  map.fitBounds([[Math.min(...xs), Math.min(...ys)], [Math.max(...xs), Math.max(...ys)]], {maxZoom:18, padding:60, duration:LOC.first ? 1200 : 500});
}
function locStop(keepErr){
  if (LOC.id != null) navigator.geolocation.clearWatch(LOC.id);
  LOC.id = null; LOC.follow = false; locShow(false); if (!keepErr) fabState('');
}
function locStart(){
  LOC.first = true; LOC.follow = true; fabState('wait');
  LOC.id = navigator.geolocation.watchPosition(p => {
      LOC.last = p; locDraw(p); locShow(true); geoShow(p); fabState('on');
      if (LOC.follow) locView(p); LOC.first = false;
    }, e => { if (e.code === 3 && LOC.last) return; geoErr(e); locStop(true); fabState('err'); },
    {enableHighAccuracy:GEO_HI, maximumAge:0, timeout:GEO_HI ? 20000 : 10000});
}
map.on('movestart', e => { if (e.originalEvent) LOC.follow = false; });   // người dùng kéo/phóng: thôi bám theo
// Nút tròn "Vị trí của tôi"
const fab = document.getElementById('locateBtn');
const fabState = st => { fab.classList.toggle('wait', st === 'wait'); fab.classList.toggle('on', st === 'on'); fab.classList.toggle('err', st === 'err'); fab.setAttribute('aria-pressed', st === 'on' || st === 'wait'); };
fab.onclick = () => {
  if (!('geolocation' in navigator)) { geoErr({code:2, message:'unsupported'}); fabState('err'); return; }
  if (geoDenied) { geoErr({code:1, message:'denied'}); fabState('err'); return; }
  if (LOC.id != null) {
    if (!LOC.follow && LOC.last) { LOC.follow = true; locView(LOC.last); geoShow(LOC.last); return; }   // đã kéo đi chỗ khác: về lại vị trí
    locStop(); geoEl.hidden = true; document.getElementById('legend').classList.remove('under'); return;   // đang ở vị trí: tắt định vị
  }
  locStart();
};
document.getElementById('geoX').onclick = () => { geoEl.hidden = true; document.getElementById('legend').classList.remove('under'); };
let geoDenied = false;
try { navigator.permissions.query({name:'geolocation'}).then(st => { geoDenied = st.state === 'denied'; st.onchange = () => { geoDenied = st.state === 'denied'; }; }).catch(() => {}); } catch (e) {}
